// The Generation 8 and 9 starter Pokémon (Grookey, Scorbunny and Sobble's lines from Sword and Shield; Sprigatito,
// Fuecoco and Quaxly's from Scarlet and Violet), added on request (2026-10-23): with the earlier generations' starters
// (already in Sun & Moon), every starter up to Generation 9. Real data: starters.json is generated by
// scripts/build-starters-data.mjs. They learn the moves they learn in their debut game (their pre-evolutions' too),
// that generation's new moves included; those moves are theirs only. No simulator imports: the UI thread and the
// worker both build their data from this.
import startersData from './starters.json';

const toId = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

export const NEW_STARTERS = startersData.species.map(s => s.name);
/** Each one's moves (by species name): what it (or a pre-evolution) learns in its debut game. */
export const STARTER_MOVES: Record<string, string[]> = Object.fromEntries(startersData.species.map(s => [s.name, s.moves]));
/** Gen 8-9 moves they learn that Gen 7 doesn't have: only the new starters may use them. */
export const STARTER_NEW_MOVES = startersData.newMoves;
/** Gen 8 Abilities they have that Gen 7 doesn't (Libero). */
export const STARTER_NEW_ABILITIES = startersData.newAbilities;
export const STARTER_NEW_MOVE_IDS = new Set(STARTER_NEW_MOVES.map(toId));
const LEARNS = new Map(startersData.species.map(s => [toId(s.name), new Set(s.moves.map(toId))]));
const DEBUT = new Map(startersData.species.map(s => [toId(s.name), s.gen]));

/** Whether a new starter learns the move (null: not one of them). */
export function starterCanLearn(speciesId: string, moveId: string): boolean | null {
  return LEARNS.get(speciesId)?.has(moveId) ?? null;
}

/** The game a new starter's moves come from ("Sword and Shield", "Scarlet and Violet"), or null. */
export function starterDebutGame(speciesId: string): string | null {
  const gen = DEBUT.get(speciesId);
  return gen === 8 ? 'Sword and Shield' : gen === 9 ? 'Scarlet and Violet' : null;
}

/**
 * Data layered on Showdown's Gen 7 data (as mod data, `inherit: true` entries): the starters, their new moves and
 * Libero stop being "Future" (Showdown derives that from the entry's generation). Libero works as in Sword and Shield:
 * before every move (Gen 9's once-per-switch-in limit came later, as for Protean, which keeps its Gen 7 behaviour).
 */
export function startersOverrides() {
  const species = Object.fromEntries(NEW_STARTERS.map(n => [toId(n), { inherit: true, gen: 7 }]));
  const formatsData = Object.fromEntries(NEW_STARTERS.map(n => [toId(n), { inherit: true, isNonstandard: null, tier: 'OU' }]));
  const moves = Object.fromEntries(STARTER_NEW_MOVES.map(n => [toId(n), { inherit: true, gen: 7, isNonstandard: null }]));
  const abilities = Object.fromEntries(STARTER_NEW_ABILITIES.map(n => [toId(n), { inherit: true, gen: 7, isNonstandard: null }]));
  return { Species: species, FormatsData: formatsData, Moves: moves, Abilities: abilities };
}
